"use client";

import {
  AccountCircleOutlined, AddRounded, ArrowOutwardRounded, AutoAwesomeOutlined,
  CheckRounded, ChevronRightRounded, CloseRounded, CodeRounded, ComputerRounded,
  ContentCopyRounded, DashboardOutlined, DevicesOutlined, DownloadRounded, FolderOpenOutlined, GitHub,
  GroupsOutlined, HistoryOutlined, HubOutlined, InsightsOutlined, LinkRounded,
  LockOutlined, MenuRounded, MoreHorizRounded, NotificationsNoneRounded,
  LogoutRounded, PauseRounded, PersonAddAltOutlined, PlayArrowRounded, PowerSettingsNewRounded, ReplayRounded, SearchRounded,
  SettingsOutlined, ShieldOutlined, TaskAltOutlined, TuneRounded,
} from "@mui/icons-material";
import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { createClient } from "../../lib/supabase/client";
import { useCrewboardData, type AgentRow, type ActivityRow, type DeviceRow, type DeviceSessionRow, type ProjectRow, type TaskProgressRow, type TaskRow, type TaskRunRow } from "./use-crewboard-data";

export type ProductPage = "dashboard" | "network" | "parties" | "repositories" | "agents" | "tasks" | "activity" | "people" | "devices" | "usage" | "profile" | "settings" | "docs";
type AgentState = "ready" | "working" | "paused" | "offline";
type Agent = { id: string; name: string; model: string; provider: string; owner: string; state: AgentState; task: string; usage: string; tone: string; row: AgentRow };
type Task = { id: string; title: string; description: string; priority: string; owner: string; agent: string; status: string; progress: string; kind: string; parentId: string | null; row: TaskRow };
type ActivityItem = { id: number; initials: string; text: string; time: string; type: string };

const modelOptions: Record<string, { value: string; label: string; context: number | null }[]> = {
  claude: [
    { value: "opus", label: "Opus 5 — strongest", context: 1_000_000 },
    { value: "sonnet", label: "Sonnet 5 — balanced", context: 1_000_000 },
    { value: "fable", label: "Fable 5 — long-running", context: 1_000_000 },
  ],
  codex: [
    { value: "gpt-5.6-sol", label: "GPT-5.6 Sol — strongest", context: 1_050_000 },
    { value: "gpt-5.6-terra", label: "GPT-5.6 Terra — balanced", context: 1_050_000 },
    { value: "gpt-5.6-luna", label: "GPT-5.6 Luna — fast", context: 1_050_000 },
  ],
  cursor: [
    { value: "auto", label: "Auto — Cursor chooses", context: 200_000 },
    { value: "opus-5", label: "Opus 5", context: 200_000 },
    { value: "gpt-5.6-sol", label: "GPT-5.6 Sol", context: 200_000 },
  ],
};

const effortOptions = [
  { value: "low", label: "Low", note: "Fastest; good for simple tasks" },
  { value: "medium", label: "Medium", note: "Balanced speed and thinking" },
  { value: "high", label: "High", note: "More thorough for harder work" },
  { value: "xhigh", label: "Extra high", note: "Deep reasoning; slower" },
  { value: "max", label: "Maximum", note: "Most reasoning; slowest" },
];

function effortLabel(value: string) { return value === "auto" ? "Automatic" : effortOptions.find((option) => option.value === value)?.label ?? "Medium"; }

function errorMessage(error: unknown, fallback: string) {
  if (error instanceof Error) return error.message;
  if (error && typeof error === "object" && "message" in error && typeof error.message === "string") return error.message;
  return fallback;
}

function providerName(provider: string) { return provider === "claude" ? "Claude Code" : provider === "codex" ? "Codex (ChatGPT)" : provider === "cursor" ? "Cursor" : provider; }
function compactTokens(value: number) { return value >= 1_000_000 ? `${(value / 1_000_000).toFixed(value % 1_000_000 ? 1 : 0)}M` : value >= 1_000 ? `${Math.round(value / 1_000)}K` : `${value}`; }
function dateTime(value: string) { return new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)); }
function runDuration(startedAt: string, finishedAt?: string | null) { const seconds = Math.max(0, Math.round((new Date(finishedAt || Date.now()).getTime() - new Date(startedAt).getTime()) / 1000)); return seconds < 60 ? `${seconds}s` : seconds < 3600 ? `${Math.floor(seconds / 60)}m ${seconds % 60}s` : `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`; }
function failureHelp(summary: string | null, errorCode: string | null) {
  const raw = summary || "The local agent stopped before returning a result.";
  if (/requires a newer version of Codex/i.test(raw)) return { title: "Codex needs an update", copy: "Update the Codex app or CLI on the assigned computer, restart the Crewboard connector, then retry this task.", raw };
  if (/service_tier/i.test(raw) && /unknown variant/i.test(raw)) return { title: "Codex has an unsupported service tier", copy: "Open ~/.codex/config.toml and change service_tier from “default” to “flex” or “fast”. Restart the connector, then retry.", raw };
  if (errorCode === "lease_expired") return { title: "The computer went offline", copy: "Bring the assigned computer and connector back online, then retry the task.", raw };
  return { title: "The agent run failed", copy: "Check the technical details below, correct the local tool or repository problem, then retry.", raw };
}

const pageMeta: Record<ProductPage, { code: string; title: string; description: string }> = {
  dashboard: { code: "PARTY / OVERVIEW", title: "Your party", description: "Coordinate people and AI agents from one shared workspace." },
  network: { code: "CREWBOARD / NETWORK", title: "Your network", description: "See every person, agent, and computer available across your parties." },
  parties: { code: "CREWBOARD / PARTIES", title: "Parties", description: "Separate workspaces for each team, project, or mission." },
  repositories: { code: "WORKSPACE / REPOSITORIES", title: "Repositories", description: "Choose exactly which folders your party's agents may work inside." },
  agents: { code: "WORKSPACE / AGENTS", title: "AI teammates", description: "Manage the models connected by everyone in this party." },
  tasks: { code: "WORKSPACE / TASKS", title: "Tasks", description: "Hand off work, follow progress, and review what your agents deliver." },
  activity: { code: "WORKSPACE / ACTIVITY", title: "Activity", description: "A live audit trail of people, agents, tasks, and connector events." },
  people: { code: "PARTY / PEOPLE", title: "People", description: "Invite collaborators and control what each person can do." },
  devices: { code: "PARTY / DEVICES", title: "Devices", description: "Computers running the local connector for this party." },
  usage: { code: "ACCOUNT / USAGE", title: "Usage", description: "Watch tokens, cost, and model activity as work happens." },
  profile: { code: "ACCOUNT / PROFILE", title: "Your profile", description: "The identity your teammates see across Crewboard." },
  settings: { code: "ACCOUNT / SETTINGS", title: "Settings", description: "Control notifications, approvals, privacy, and account behavior." },
  docs: { code: "CREWBOARD / DOCS", title: "Documentation", description: "Connect your first AI tool and learn how a Crewboard party works." },
};

function initialsFor(label: string) { return label.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase() || "ME"; }
function StateBadge({ state }: { state: AgentState }) { return <span className={`state-badge ${state}`}><i />{state}</span>; }
function timeAgo(value: string) { const seconds = Math.max(1, Math.floor((Date.now() - new Date(value).getTime()) / 1000)); if (seconds < 60) return `${seconds}s`; if (seconds < 3600) return `${Math.floor(seconds / 60)}m`; if (seconds < 86400) return `${Math.floor(seconds / 3600)}h`; return `${Math.floor(seconds / 86400)}d`; }
function isDeviceOnline(device: DeviceRow) { return device.status === "online" && Boolean(device.last_seen_at) && Date.now() - new Date(device.last_seen_at as string).getTime() < 90_000; }
function activityCopy(event: ActivityRow, actorName: string): ActivityItem { const metadata = event.metadata && typeof event.metadata === "object" && !Array.isArray(event.metadata) ? event.metadata as Record<string, unknown> : {}; const subject = typeof metadata.title === "string" ? metadata.title : typeof metadata.name === "string" ? metadata.name : "the workspace"; const label = event.event_type.replaceAll("_", " "); return { id: event.id, initials: initialsFor(actorName), text: `${actorName} ${label} ${subject}`.trim(), time: timeAgo(event.created_at), type: event.event_type.split("_")[0] || "Activity" }; }

function ConnectorModal({ partyId, onClose, onConnected }: { partyId: string; onClose: () => void; onConnected: () => void | Promise<void> }) {
  const [step, setStep] = useState(1);
  const [copied, setCopied] = useState(false);
  const [pairingCode, setPairingCode] = useState("");
  const [message, setMessage] = useState("");
  const [approving, setApproving] = useState(false);
  const [startAtLogin, setStartAtLogin] = useState(true);
  const [command, setCommand] = useState("npx --yes github:mmvinfo28/crewboard#connector-v0.4.1 connect");
  useEffect(() => { setCommand(`npx --yes github:mmvinfo28/crewboard#connector-v0.4.1 connect --url ${window.location.origin}`); }, []);
  async function approvePairing() { if (!partyId || !pairingCode.trim()) return; setApproving(true); setMessage(""); try { const response = await fetch("/api/connector/pair/approve", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ code: pairingCode.trim(), partyId }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error?.message ?? "Could not approve this computer"); await onConnected(); onClose(); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not approve this computer"); setApproving(false); } }
  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal" role="dialog" aria-modal="true" aria-labelledby="connector-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">CONNECTOR / 0{step}</span><h2 id="connector-title">Connect this computer</h2></div><button className="icon-button" aria-label="Close connector setup" onClick={onClose}><CloseRounded /></button></header>
    <div className="step-line" aria-label={`Step ${step} of 3`}>{[1, 2, 3].map((item) => <span key={item} className={item <= step ? "active" : ""} />)}</div>
    {step === 1 && <div className="modal-body"><div className="setup-illustration"><ComputerRounded /></div><h3>Your AI stays on your machine.</h3><p>The connector lets this party send approved tasks to AI tools already installed on your computer.</p><div className="safety-list"><div><LockOutlined /><span><strong>Logins stay local</strong>Claude, Codex, and Cursor credentials never go to Crewboard.</span></div><div><FolderOpenOutlined /><span><strong>You choose the folders</strong>Only approved project folders can be accessed.</span></div><div><TaskAltOutlined /><span><strong>You control approvals</strong>Review sensitive actions before an agent runs them.</span></div></div></div>}
    {step === 2 && <div className="modal-body"><div className="setup-illustration"><DownloadRounded /></div><h3>Download the Crewboard companion.</h3><p>Open the downloaded file and leave its small window running. You only pair this computer once.</p><label className="startup-choice"><input type="checkbox" checked={startAtLogin} onChange={(event) => setStartAtLogin(event.target.checked)} /><span><strong>Start Crewboard when I sign in</strong><small>Queued tasks can continue after restarting the laptop.</small></span></label><a className="button primary download-connector" href={`/api/connector/launcher/windows?startup=${startAtLogin ? "1" : "0"}`} download><DownloadRounded />Download for Windows</a><details className="manual-setup"><summary>Mac, Linux, or manual setup</summary><button className="command-box" onClick={() => { navigator.clipboard?.writeText(command); setCopied(true); }}><code>{command}</code><span>{copied ? <CheckRounded /> : <ContentCopyRounded />}{copied ? "Copied" : "Copy"}</span></button></details><p className="quiet-note">Beta launcher. The release installer will be code-signed before public launch.</p></div>}
    {step === 3 && <div className="modal-body"><div className="setup-illustration"><LinkRounded /></div><h3>Enter the pairing code.</h3><p>The connector prints a short code in your terminal. Approving it links only this computer and this party.</p><label>Pairing code<input value={pairingCode} onChange={(event) => setPairingCode(event.target.value.toUpperCase())} placeholder="ABCD-1234" autoFocus /></label>{message && <div className="auth-message">{message}</div>}</div>}
    <footer className="modal-footer"><span>Step {step} of 3</span><div>{step > 1 && <button className="button ghost" onClick={() => setStep(step - 1)}>Back</button>}<button className="button primary" disabled={step === 3 && (!partyId || !pairingCode.trim() || approving)} onClick={() => { if (step < 3) setStep(step + 1); else void approvePairing(); }}>{step === 1 ? "Continue" : step === 2 ? "I have a code" : approving ? "Approving…" : "Approve computer"}<ChevronRightRounded /></button></div></footer>
  </section></div>;
}

function AgentModal({ tools, devices, onClose, onCreate, onConnect }: { tools: AgentRow[]; devices: DeviceRow[]; onClose: () => void; onCreate: (input: { deviceId: string; name: string; provider: string; model: string; reasoningEffort: string; instructions: string; contextWindowTokens: number | null }) => Promise<void>; onConnect: () => void }) {
  const ownedDevices = devices.filter(isDeviceOnline);
  const [deviceId, setDeviceId] = useState(ownedDevices[0]?.id ?? "");
  const availableTools = tools.filter((tool) => tool.device_id === deviceId);
  const [toolId, setToolId] = useState(availableTools[0]?.id ?? "");
  const selectedTool = tools.find((tool) => tool.id === toolId && tool.device_id === deviceId) ?? availableTools[0];
  const provider = selectedTool?.provider ?? "";
  const options = modelOptions[provider] ?? [];
  const [model, setModel] = useState(options[0]?.value ?? "");
  const [reasoningEffort, setReasoningEffort] = useState("medium");
  const [name, setName] = useState("");
  const [instructions, setInstructions] = useState("");
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => { setModel(modelOptions[provider]?.[0]?.value ?? ""); setReasoningEffort(provider === "cursor" ? "auto" : "medium"); }, [provider]);
  function chooseDevice(nextDeviceId: string) {
    const firstTool = tools.find((tool) => tool.device_id === nextDeviceId);
    setDeviceId(nextDeviceId);
    setToolId(firstTool?.id ?? "");
  }

  async function submit() {
    if (!deviceId || !provider || !model || !name.trim()) return;
    setSubmitting(true); setMessage("");
    const selected = (modelOptions[provider] ?? []).find((option) => option.value === model);
    try {
      await onCreate({ deviceId, name: name.trim(), provider, model, reasoningEffort, instructions, contextWindowTokens: selected?.context ?? null });
      onClose();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not create this agent");
      setSubmitting(false);
    }
  }

  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal agent-modal" role="dialog" aria-modal="true" aria-labelledby="agent-modal-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">AGENT / CREATE</span><h2 id="agent-modal-title">Create an AI teammate</h2></div><button className="icon-button" aria-label="Close agent setup" onClick={onClose}><CloseRounded /></button></header>
    {!tools.length ? <div className="modal-body"><div className="setup-illustration"><HubOutlined /></div><h3>No AI tools detected yet.</h3><p>Connect a computer first. Crewboard will find Claude Code, Codex, and Cursor installed on it.</p><button className="button primary modal-main-action" onClick={onConnect}>Connect a computer<ArrowOutwardRounded /></button></div> : <div className="agent-form">
      <div className="agent-form-intro"><span className="agent-mark violet">{name.trim().charAt(0).toUpperCase() || "A"}</span><div><strong>{name.trim() || "Name your teammate"}</strong><small>{provider ? `${providerName(provider)} · ${model || "Choose a model"}` : "Choose an installed tool"}</small></div></div>
      <div className="agent-form-grid"><label>Computer<select value={deviceId} onChange={(event) => chooseDevice(event.target.value)}>{ownedDevices.map((device) => <option key={device.id} value={device.id}>{device.name}</option>)}</select></label><label>Installed tool<select value={selectedTool?.id ?? ""} onChange={(event) => setToolId(event.target.value)}>{availableTools.map((tool) => <option key={tool.id} value={tool.id}>{providerName(tool.provider)} · detected {tool.model}</option>)}</select></label></div>
      <label>Agent name<input autoFocus value={name} onChange={(event) => setName(event.target.value)} maxLength={100} placeholder="Bob" /></label>
      <label>Model<select value={model} onChange={(event) => setModel(event.target.value)}>{options.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select><small>This is passed to the local tool when this agent runs.</small></label>
      <label>Reasoning effort<select value={reasoningEffort} disabled={provider === "cursor"} onChange={(event) => setReasoningEffort(event.target.value)}>{provider === "cursor" ? <option value="auto">Automatic — managed by Cursor</option> : effortOptions.map((option) => <option key={option.value} value={option.value}>{option.label} — {option.note}</option>)}</select><small>Higher effort can improve difficult work, but takes longer and uses more of your provider subscription.</small></label>
      <label>Standing instructions <span>optional</span><textarea value={instructions} onChange={(event) => setInstructions(event.target.value)} maxLength={8000} rows={5} placeholder="You are the careful reviewer. Check tests and explain risks before editing…" /></label>
      {message && <div className="auth-message">{message}</div>}
    </div>}
    <footer className="modal-footer"><span>One installed tool can power many differently named agents.</span><div><button className="button ghost" onClick={onClose}>Cancel</button>{tools.length > 0 && <button className="button primary" disabled={!name.trim() || !deviceId || !provider || !model || submitting} onClick={() => void submit()}>{submitting ? "Creating…" : "Create agent"}<ChevronRightRounded /></button>}</div></footer>
  </section></div>;
}

function TaskModal({ agents, projects, onClose, onCreate }: { agents: Agent[]; projects: ProjectRow[]; onClose: () => void; onCreate: (input: { title: string; description: string; assignedAgentId?: string; projectId?: string; priority: string; autoSplit: boolean; splitAgentIds: string[] }) => Promise<void> }) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [agentId, setAgentId] = useState("");
  const [mode, setMode] = useState<"single" | "split">(agents.length >= 2 ? "split" : "single");
  const [splitAgentIds, setSplitAgentIds] = useState<string[]>(agents.filter((agent) => agent.state !== "offline").slice(0, 4).map((agent) => agent.id));
  const [projectId, setProjectId] = useState("");
  const [priority, setPriority] = useState("medium");
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const selectedProject = projects.find((project) => project.id === projectId);
  const splitHasCoordinator = agents.some((agent) => splitAgentIds.includes(agent.id) && agent.provider !== "cursor");
  function toggleSplitAgent(id: string) { setSplitAgentIds((ids) => ids.includes(id) ? ids.filter((item) => item !== id) : [...ids, id]); }
  async function submit() {
    if (!title.trim()) return;
    if (mode === "split" && splitAgentIds.length < 2) { setMessage("Choose at least two agents for an automatic split"); return; }
    if (mode === "split" && !splitHasCoordinator) { setMessage("Choose at least one Claude or Codex agent to coordinate the split"); return; }
    setSubmitting(true); setMessage("");
    try { await onCreate({ title: title.trim(), description: description.trim(), assignedAgentId: mode === "single" ? agentId || undefined : undefined, projectId: projectId || undefined, priority, autoSplit: mode === "split", splitAgentIds: mode === "split" ? splitAgentIds : [] }); onClose(); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Could not create the task"); setSubmitting(false); }
  }
  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal task-modal" role="dialog" aria-modal="true" aria-labelledby="task-modal-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">GOAL / NEW</span><h2 id="task-modal-title">Give your crew a goal</h2></div><button className="icon-button" aria-label="Close task setup" onClick={onClose}><CloseRounded /></button></header>
    <div className="agent-form"><div className="task-mode-switch" role="group" aria-label="Task assignment mode"><button className={mode === "split" ? "active" : ""} onClick={() => setMode("split")} disabled={agents.length < 2}><AutoAwesomeOutlined /><span><strong>Split automatically</strong><small>A coordinator divides the goal across your agents.</small></span></button><button className={mode === "single" ? "active" : ""} onClick={() => setMode("single")}><PersonAddAltOutlined /><span><strong>Single agent</strong><small>Send one focused task to one teammate.</small></span></button></div><label>What outcome do you want?<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} maxLength={160} placeholder="Build and test the account settings page" /></label><label>Details <span>optional</span><textarea value={description} onChange={(event) => setDescription(event.target.value)} rows={5} placeholder="Describe the outcome, useful context, constraints, and how to know it is done…" /></label>{mode === "split" ? <fieldset className="split-agent-picker"><legend>Agents in this split <span>{splitAgentIds.length} selected</span></legend><div>{agents.map((agent) => <button type="button" className={splitAgentIds.includes(agent.id) ? "selected" : ""} disabled={agent.state === "offline"} key={agent.id} onClick={() => toggleSplitAgent(agent.id)}><span className={`agent-mark ${agent.tone}`}>{agent.name.charAt(0)}</span><span><strong>{agent.name}</strong><small>{providerName(agent.provider)} · {agent.model}</small></span>{splitAgentIds.includes(agent.id) && <CheckRounded />}</button>)}</div><small>The first available Claude or Codex teammate coordinates the plan. Every selected agent receives a real child task.</small></fieldset> : <label>Assign to<select value={agentId} onChange={(event) => setAgentId(event.target.value)}><option value="">Any available agent</option>{agents.map((agent) => <option key={agent.id} value={agent.id}>{agent.name} · {providerName(agent.provider)} · {agent.model}</option>)}</select></label>}<div className="agent-form-grid"><label>Repository<select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">No repository (planning only)</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.source_type === "github" ? "GitHub" : "Local"} · {project.name}</option>)}</select>{selectedProject && <small className="field-hint">{selectedProject.repository_url || "Files stay in the folder chosen on the connected computer."}</small>}</label><label>Priority<select value={priority} onChange={(event) => setPriority(event.target.value)}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="critical">Critical</option></select></label></div>{message && <div className="auth-message">{message}</div>}</div>
    <footer className="modal-footer"><span>{mode === "split" ? "Planning uses one short local subscription run." : "The connector picks it up automatically."}</span><div><button className="button ghost" onClick={onClose}>Cancel</button><button className="button primary" disabled={!title.trim() || submitting || (mode === "split" && (splitAgentIds.length < 2 || !splitHasCoordinator))} onClick={() => void submit()}>{submitting ? "Adding…" : mode === "split" ? "Split and start" : "Add task"}<ChevronRightRounded /></button></div></footer>
  </section></div>;
}

function RepositoryModal({ devices, onClose, onRequest, onConnect }: { devices: DeviceRow[]; onClose: () => void; onRequest: (input: { name: string; deviceId: string; sourceType: "local" | "github"; repositoryUrl?: string }) => Promise<void>; onConnect: () => void }) {
  const availableDevices = devices.filter(isDeviceOnline);
  const [name, setName] = useState("");
  const [sourceType, setSourceType] = useState<"local" | "github">("github");
  const [repositoryUrl, setRepositoryUrl] = useState("");
  const [deviceId, setDeviceId] = useState(availableDevices[0]?.id ?? "");
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [requested, setRequested] = useState(false);

  async function submit() {
    const inferredName = repositoryUrl.trim().split("/").filter(Boolean).at(-1)?.replace(/\.git$/i, "") || "";
    const finalName = name.trim() || inferredName;
    if (!finalName || !deviceId || (sourceType === "github" && !repositoryUrl.trim())) return;
    setSubmitting(true);
    setMessage("");
    try {
      await onRequest({ name: finalName, deviceId, sourceType, repositoryUrl: sourceType === "github" ? repositoryUrl.trim() : undefined });
      setRequested(true);
    } catch (error) {
      setMessage(errorMessage(error, "Could not connect the repository"));
    } finally {
      setSubmitting(false);
    }
  }

  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal repository-modal" role="dialog" aria-modal="true" aria-labelledby="repository-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">REPOSITORY / ADD</span><h2 id="repository-title">Add a repository</h2></div><button className="icon-button" aria-label="Close repository setup" onClick={onClose}><CloseRounded /></button></header>
    {!availableDevices.length ? <div className="modal-body"><div className="setup-illustration"><ComputerRounded /></div><h3>Connect your computer first.</h3><p>The connector clones the repository and runs your subscribed AI tools on that computer.</p><button className="button primary modal-main-action" onClick={onConnect}>Connect this computer<ArrowOutwardRounded /></button></div> : requested ? <div className="modal-body"><div className="setup-illustration success">{sourceType === "github" ? <GitHub /> : <FolderOpenOutlined />}</div><h3>{sourceType === "github" ? "Repository is being cloned." : "Choose the folder on your computer."}</h3><p>{sourceType === "github" ? `${availableDevices.find((device) => device.id === deviceId)?.name} is cloning the repository using its local GitHub login.` : `A normal folder picker should now be open on ${availableDevices.find((device) => device.id === deviceId)?.name}. The local path never leaves that computer.`}</p></div> : <div className="modal-body repository-form"><div className="repository-source-switch"><button className={sourceType === "github" ? "active" : ""} onClick={() => setSourceType("github")}><GitHub />GitHub URL</button><button className={sourceType === "local" ? "active" : ""} onClick={() => setSourceType("local")}><FolderOpenOutlined />Local folder</button></div><div className="setup-illustration">{sourceType === "github" ? <GitHub /> : <FolderOpenOutlined />}</div><h3>{sourceType === "github" ? "Connect a GitHub repository" : "Use a folder already on this computer"}</h3><p>{sourceType === "github" ? "Paste the normal GitHub link. The connector clones it remotely; private repositories use the GitHub login already on that computer." : "Crewboard opens a folder picker on the selected computer."}</p>{sourceType === "github" && <label>GitHub repository URL<input value={repositoryUrl} onChange={(event) => setRepositoryUrl(event.target.value)} maxLength={500} placeholder="https://github.com/owner/repository" autoFocus /></label>}<label>Display name <span>optional</span><input value={name} onChange={(event) => setName(event.target.value)} maxLength={120} placeholder={sourceType === "github" ? "Taken from the GitHub URL" : "Website redesign"} autoFocus={sourceType === "local"} /></label><label>Run on computer<select value={deviceId} onChange={(event) => setDeviceId(event.target.value)}>{availableDevices.map((device) => <option key={device.id} value={device.id}>{device.name}</option>)}</select></label>{message && <div className="auth-message">{message}</div>}</div>}
    <footer className="modal-footer"><span>{requested ? sourceType === "github" ? "Cloning through the local connector" : "Waiting for your folder choice" : sourceType === "github" ? "No repository files are uploaded to Crewboard" : "Only the chosen folder can be accessed"}</span><div><button className="button ghost" onClick={onClose}>{requested ? "Done" : "Cancel"}</button>{availableDevices.length > 0 && !requested && <button className="button primary" disabled={!deviceId || submitting || (sourceType === "github" ? !repositoryUrl.trim() : !name.trim())} onClick={() => void submit()}>{submitting ? sourceType === "github" ? "Cloning…" : "Opening…" : sourceType === "github" ? "Clone repository" : "Choose folder"}<ChevronRightRounded /></button>}</div></footer>
  </section></div>;
}

function TaskDetailModal({ task, children, runs, progress, agents, projects, devices, onClose, onResume, onRetry, onOpenTask }: { task: Task; children: Task[]; runs: TaskRunRow[]; progress: TaskProgressRow[]; agents: Agent[]; projects: ProjectRow[]; devices: DeviceRow[]; onClose: () => void; onResume: (taskId: string) => Promise<void>; onRetry: (taskId: string) => Promise<void>; onOpenTask: (taskId: string) => void }) {
  const [busyAction, setBusyAction] = useState<"resume" | "retry" | "">("");
  const [message, setMessage] = useState("");
  const taskRuns = runs.filter((run) => run.task_id === task.id).sort((left, right) => new Date(right.created_at).getTime() - new Date(left.created_at).getTime());
  const latestRun = taskRuns[0];
  const events = progress.filter((event) => event.task_id === task.id).sort((left, right) => new Date(left.created_at).getTime() - new Date(right.created_at).getTime());
  const assignedAgent = agents.find((agent) => agent.id === task.row.assigned_agent_id);
  const project = projects.find((item) => item.id === task.row.project_id);
  const device = devices.find((item) => item.id === (latestRun?.device_id || task.row.assigned_device_id || assignedAgent?.row.device_id));
  const lastEvent = events.at(-1);
  const failure = task.status === "failed" && latestRun ? failureHelp(latestRun.result_summary, latestRun.error_code) : null;
  async function act(kind: "resume" | "retry") { setBusyAction(kind); setMessage(""); try { await (kind === "resume" ? onResume(task.id) : onRetry(task.id)); onClose(); } catch (error) { setMessage(error instanceof Error ? error.message : `Could not ${kind} this task`); setBusyAction(""); } }
  return <div className="modal-backdrop task-detail-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal task-detail-modal" role="dialog" aria-modal="true" aria-labelledby="task-detail-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">{task.kind === "planner" ? "SPLIT GOAL" : "TASK"} / {task.status.toUpperCase()}</span><h2 id="task-detail-title">{task.title}</h2></div><button className="icon-button" aria-label="Close task progress" onClick={onClose}><CloseRounded /></button></header>
    <div className="task-detail-body"><div className="task-detail-summary"><div><span className={`task-status-large ${task.status}`}><i />{task.status}</span><span className={`priority-chip ${task.priority}`}>{task.priority}</span></div><p>{task.description || "No additional instructions."}</p><dl><div><dt>Agent</dt><dd>{assignedAgent ? `${assignedAgent.name} · ${providerName(assignedAgent.provider)}` : task.agent}</dd></div><div><dt>Model</dt><dd>{assignedAgent?.model || "Chosen when claimed"}</dd></div><div><dt>Repository</dt><dd>{project ? `${project.source_type === "github" ? "GitHub" : "Local"} · ${project.name}` : "No repository"}</dd></div><div><dt>Computer</dt><dd>{device?.name || "Waiting for a device"}</dd></div><div><dt>Created</dt><dd>{dateTime(task.row.created_at)}</dd></div>{latestRun && <div><dt>Attempt</dt><dd>{latestRun.attempt} · {runDuration(latestRun.started_at, latestRun.finished_at)}</dd></div>}</dl></div>
      {task.status === "running" && <section className="running-now"><header><span className="live-indicator"><i />RUNNING NOW</span><small>{latestRun?.last_heartbeat_at ? `Heartbeat ${timeAgo(latestRun.last_heartbeat_at)} ago` : "Waiting for heartbeat"}</small></header><strong>{lastEvent?.message || task.progress || "The local agent is starting the task."}</strong><p>{assignedAgent ? `${assignedAgent.name} is using ${assignedAgent.model}` : task.agent}{project ? ` in ${project.name}` : ""}{device ? ` on ${device.name}` : ""}.</p></section>}
      {children.length > 0 && <section className="split-children"><header><strong>Automatic split</strong><span>{children.filter((child) => child.status === "completed").length}/{children.length} completed</span></header>{children.map((child) => <button type="button" key={child.id} onClick={() => onOpenTask(child.id)}><span className={`task-status-dot ${child.status}`} /><span><strong>{child.title}</strong><small>{child.agent} · {child.status}</small></span><ChevronRightRounded /></button>)}</section>}
      <section className="progress-timeline"><header><div><strong>Live progress</strong><small>Sanitized milestones from the local CLI</small></div>{task.status === "running" && <span className="live-indicator"><i />LIVE</span>}</header>{events.map((event) => <div className={`progress-event ${event.kind}`} key={event.id}><span><i /></span><p><strong>{event.message}</strong><time>{timeAgo(event.created_at)} ago</time></p></div>)}{!events.length && <div className="progress-empty"><HistoryOutlined /><p><strong>No progress events yet.</strong><span>Older connector versions report only the final result. Restart the connector after updating to see live milestones.</span></p></div>}</section>
      {failure && <section className="failure-summary"><span className="failure-icon">!</span><div><strong>{failure.title}</strong><p>{failure.copy}</p><details><summary>Technical details</summary><pre>{failure.raw}</pre></details></div></section>}
      {!failure && latestRun?.result_summary && <section className="result-summary"><strong>Result</strong><p>{latestRun.result_summary}</p></section>}
      {taskRuns.length > 0 && <section className="run-attempts"><header><strong>Run attempts</strong><span>{taskRuns.length}</span></header>{taskRuns.map((run) => <div key={run.id}><span className={`task-status-dot ${run.status}`} /><p><strong>Attempt {run.attempt} · {run.status}</strong><small>{dateTime(run.started_at)} · {runDuration(run.started_at, run.finished_at)}{devices.find((item) => item.id === run.device_id)?.name ? ` · ${devices.find((item) => item.id === run.device_id)?.name}` : ""}</small></p>{run.error_code && <code>{run.error_code}</code>}</div>)}</section>}
      <div className="provider-history-note"><LockOutlined /><p><strong>Crewboard is the run history.</strong><span>Headless Codex, Claude Code, and Cursor runs do not reliably appear in the consumer ChatGPT or Claude desktop chats.</span></p></div>{message && <div className="auth-message">{message}</div>}
    </div>
    <footer className="modal-footer"><span>{task.status === "interrupted" ? "The previous run stopped when its device disconnected." : task.status === "failed" ? "Fix the local issue before retrying." : `Created by ${task.owner}`}</span><div><button className="button ghost" onClick={onClose}>Close</button>{task.status === "interrupted" && <button className="button primary" disabled={Boolean(busyAction)} onClick={() => void act("resume")}><ReplayRounded />{busyAction === "resume" ? "Resuming…" : "Resume safely"}</button>}{task.status === "failed" && <button className="button primary" disabled={Boolean(busyAction)} onClick={() => void act("retry")}><ReplayRounded />{busyAction === "retry" ? "Retrying…" : "Retry task"}</button>}</div></footer>
  </section></div>;
}

function AgentDetailModal({ agent, device, currentTask, latestRun, canEdit, onUpdateEffort, onClose }: { agent: Agent; device?: DeviceRow; currentTask?: Task; latestRun?: TaskRunRow; canEdit: boolean; onUpdateEffort: (agentId: string, reasoningEffort: string) => Promise<void>; onClose: () => void }) {
  const failure = latestRun?.status === "failed" ? failureHelp(latestRun.result_summary, latestRun.error_code) : null;
  const [reasoningEffort, setReasoningEffort] = useState(agent.row.reasoning_effort || (agent.provider === "cursor" ? "auto" : "medium"));
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  async function saveEffort() {
    setSaving(true); setMessage("");
    try { await onUpdateEffort(agent.id, reasoningEffort); setMessage("Saved. This applies to the next run."); }
    catch (error) { setMessage(errorMessage(error, "Could not update reasoning effort")); }
    finally { setSaving(false); }
  }
  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal agent-detail-modal" role="dialog" aria-modal="true" aria-labelledby="agent-detail-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">AGENT / DETAILS</span><h2 id="agent-detail-title">{agent.name}</h2></div><button className="icon-button" aria-label="Close agent details" onClick={onClose}><CloseRounded /></button></header>
    <div className="agent-detail-body"><section className="agent-detail-hero"><span className={`agent-mark ${agent.tone}`}>{agent.name.charAt(0)}</span><div><strong>{providerName(agent.provider)}</strong><p>{agent.model} · {effortLabel(reasoningEffort)} effort</p></div><StateBadge state={agent.state} /></section><dl className="agent-detail-grid"><div><dt>Owner</dt><dd>{agent.owner}</dd></div><div><dt>Computer</dt><dd>{device?.name || "Not connected"}</dd></div><div><dt>Connector</dt><dd>{device?.connector_version || "Unknown"}</dd></div><div><dt>Context window</dt><dd>{agent.row.context_window_tokens ? compactTokens(agent.row.context_window_tokens) : "Not reported"}</dd></div></dl><section className="agent-effort-editor"><div><span>REASONING EFFORT</span><strong>How hard should this agent think?</strong><p>{agent.provider === "cursor" ? "Cursor chooses its effort automatically." : "Higher effort is more thorough, but slower and uses more of your provider subscription. Changes apply to the next run."}</p></div><div><select aria-label="Reasoning effort" value={reasoningEffort} disabled={!canEdit || saving || agent.provider === "cursor"} onChange={(event) => { setReasoningEffort(event.target.value); setMessage(""); }}>{agent.provider === "cursor" ? <option value="auto">Automatic</option> : effortOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select>{canEdit && agent.provider !== "cursor" && <button className="button secondary" disabled={saving || reasoningEffort === agent.row.reasoning_effort} onClick={() => void saveEffort()}>{saving ? "Saving…" : "Save effort"}</button>}</div>{message && <small className="agent-effort-message">{message}</small>}</section><section className="agent-current-work"><span>CURRENT WORK</span><strong>{currentTask?.title || agent.task}</strong><p>{currentTask ? `${currentTask.status} · ${currentTask.progress || "Waiting for an update"}` : agent.usage}</p></section><section className="agent-instructions"><span>STANDING INSTRUCTIONS</span><p>{agent.row.instructions || "No special instructions. This agent follows each task prompt."}</p></section>{latestRun && <section className="agent-last-run"><span>LAST RUN</span><strong>Attempt {latestRun.attempt} · {latestRun.status}</strong><p>{dateTime(latestRun.started_at)} · {runDuration(latestRun.started_at, latestRun.finished_at)}</p>{failure && <small>{failure.title}: {failure.copy}</small>}</section>}</div>
    <footer className="modal-footer"><span>Provider credentials stay on {device?.name || "the local computer"}.</span><button className="button primary" onClick={onClose}>Done</button></footer>
  </section></div>;
}

function DeviceManagerModal({ devices, sessions, onClose, onConnect, onRevoke }: { devices: DeviceRow[]; sessions: DeviceSessionRow[]; onClose: () => void; onConnect: () => void; onRevoke: (sessionId: string) => Promise<void> }) {
  const [busySessionId, setBusySessionId] = useState("");
  const [message, setMessage] = useState("");

  async function revoke(sessionId: string) {
    setBusySessionId(sessionId);
    setMessage("");
    try { await onRevoke(sessionId); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Could not disconnect this device"); }
    finally { setBusySessionId(""); }
  }

  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="connector-modal device-manager-modal" role="dialog" aria-modal="true" aria-labelledby="device-manager-title" onMouseDown={(event) => event.stopPropagation()}>
    <header className="modal-header"><div><span className="section-code">CONNECTOR / DEVICES</span><h2 id="device-manager-title">Manage devices</h2></div><button className="icon-button" aria-label="Close device manager" onClick={onClose}><CloseRounded /></button></header>
    <div className="device-manager-list">{devices.map((device) => { const activeSession = sessions.find((session) => session.device_id === device.id && !session.revoked_at && new Date(session.expires_at).getTime() > Date.now()); const online = isDeviceOnline(device); return <article key={device.id} className="device-manager-row"><span className="device-icon"><ComputerRounded /></span><div><strong>{device.name}</strong><small>{device.platform} · Connector {device.connector_version || "unknown"}</small><span className={`manager-state ${online ? "online" : "offline"}`}><i />{online ? "Online now" : device.last_seen_at ? `Last seen ${timeAgo(device.last_seen_at)} ago` : "Never connected"}</span></div>{activeSession ? <button className="button danger-outline" disabled={busySessionId === activeSession.id} onClick={() => void revoke(activeSession.id)}><PowerSettingsNewRounded />{busySessionId === activeSession.id ? "Disconnecting…" : "Disconnect"}</button> : <span className="session-ended">Disconnected</span>}</article>; })}{!devices.length && <div className="device-manager-empty"><ComputerRounded /><strong>No computers connected yet</strong><p>Connect the computer that runs Claude Code, Codex, or Cursor.</p></div>}</div>
    {message && <div className="auth-message device-manager-message">{message}</div>}
    <footer className="modal-footer"><span>Disconnecting revokes this party&apos;s access immediately.</span><div><button className="button ghost" onClick={onClose}>Done</button><button className="button primary" onClick={onConnect}><AddRounded />Connect another</button></div></footer>
  </section></div>;
}

function SearchPalette({ onClose }: { onClose: () => void }) {
  const [query, setQuery] = useState("");
  const items = [["Go to Network", "/network", "People and agents"], ["Open Tasks", "/tasks", "4 tasks"], ["View Usage", "/usage", "Live model spend"], ["Connector setup", "/devices", "Add this computer"], ["Account settings", "/settings", "Approvals and privacy"], ["Read the docs", "/docs", "Quickstart guide"]];
  const filtered = items.filter((item) => item.join(" ").toLowerCase().includes(query.toLowerCase()));
  return <div className="modal-backdrop search-backdrop" onMouseDown={onClose}><section className="search-palette" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}><div className="palette-input"><SearchRounded /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search Crewboard…" /><kbd>ESC</kbd></div><div className="palette-results">{filtered.map(([label, href, note]) => <Link key={href} href={href} onClick={onClose}><span><strong>{label}</strong><small>{note}</small></span><ChevronRightRounded /></Link>)}</div></section></div>;
}

function PageHeading({ page, actions, partyName }: { page: ProductPage; actions?: React.ReactNode; partyName?: string }) {
  const meta = pageMeta[page];
  return <div className="page-heading"><div><span className="section-code">{meta.code}</span><h1>{page === "dashboard" && partyName ? partyName : meta.title}</h1><p>{meta.description}</p></div>{actions && <div className="heading-actions">{actions}</div>}</div>;
}

export default function ProductApp({ page }: { page: ProductPage }) {
  const data = useCrewboardData();
  const [connectorOpen, setConnectorOpen] = useState(false);
  const [deviceManagerOpen, setDeviceManagerOpen] = useState(false);
  const [repositoryOpen, setRepositoryOpen] = useState(false);
  const [agentOpen, setAgentOpen] = useState(false);
  const [taskOpen, setTaskOpen] = useState(false);
  const [selectedTaskId, setSelectedTaskId] = useState("");
  const [selectedAgentId, setSelectedAgentId] = useState("");
  const [mobileNav, setMobileNav] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [profileDraft, setProfileDraft] = useState("");
  const [profileMessage, setProfileMessage] = useState("");
  const [taskMessage, setTaskMessage] = useState("");
  const [networkQuery, setNetworkQuery] = useState("");
  const [partyName, setPartyName] = useState("");
  const [partyMessage, setPartyMessage] = useState("");
  const [copied, setCopied] = useState(false);
  const [cloudConnected, setCloudConnected] = useState(false);
  const [settings, setSettings] = useState({ approvals: true, taskUpdates: true, weeklyDigest: false, presence: true });

  const memberById = useMemo(() => new Map(data.members.map((member) => [member.user_id, member.displayName])), [data.members]);
  const agentById = useMemo(() => new Map(data.agents.map((agent) => [agent.id, agent.name])), [data.agents]);
  const deviceById = useMemo(() => new Map(data.devices.map((device) => [device.id, device])), [data.devices]);
  const providerTools = useMemo(() => data.agents.filter((agent) => agent.is_default), [data.agents]);
  const agents: Agent[] = useMemo(() => data.agents.filter((agent) => !agent.is_default).map((agent, index) => {
    const lastUsage = data.usageEvents.find((event) => event.agent_id === agent.id);
    const usedTokens = lastUsage ? lastUsage.input_tokens + lastUsage.output_tokens : 0;
    const remaining = agent.context_window_tokens && lastUsage ? Math.max(0, agent.context_window_tokens - usedTokens) : null;
    return {
    id: agent.id,
    name: agent.name,
    model: agent.model,
    provider: agent.provider,
    owner: agent.owner_id === data.userId ? "You" : memberById.get(agent.owner_id) ?? "Member",
    state: (agent.device_id && deviceById.get(agent.device_id)?.status !== "online" ? "offline" : ["ready", "working", "paused", "offline"].includes(agent.status) ? agent.status : "offline") as AgentState,
    task: agent.current_task_summary || (agent.status === "offline" ? "Device disconnected" : "Waiting for a task"),
    usage: lastUsage ? `${compactTokens(usedTokens)} last run${remaining !== null ? ` · ~${compactTokens(remaining)} context left` : ""}` : "No runs recorded yet",
    tone: ["violet", "charcoal", "blue", "amber"][index % 4],
    row: agent,
  }; }), [data.agents, data.usageEvents, data.userId, memberById, deviceById]);
  const tasks: Task[] = useMemo(() => data.tasks.map((task) => ({
    id: task.id,
    title: task.title,
    description: task.description,
    priority: task.priority,
    owner: task.created_by === data.userId ? "You" : memberById.get(task.created_by) ?? "Member",
    agent: task.assigned_agent_id ? agentById.get(task.assigned_agent_id) ?? "Assigned agent" : "Unassigned",
    status: task.status,
    progress: task.progress_summary || "",
    kind: task.task_kind,
    parentId: task.parent_task_id,
    row: task,
  })), [data.tasks, data.userId, memberById, agentById]);
  const selectedTask = tasks.find((task) => task.id === selectedTaskId) ?? null;
  const selectedAgent = agents.find((agent) => agent.id === selectedAgentId) ?? null;
  const activity = useMemo(() => data.activity.map((event) => activityCopy(event, event.actor_id === data.userId ? "You" : memberById.get(event.actor_id ?? "") ?? "Crewboard")), [data.activity, data.userId, memberById]);
  const connected = data.devices.some(isDeviceOnline);
  const canManageAllDevices = ["owner", "admin"].includes(data.activeParty?.role ?? "");
  const manageableDevices = data.devices.filter((device) => canManageAllDevices || device.owner_id === data.userId);
  const activePartyName = data.activeParty?.name ?? "No party selected";
  const activePartyInitials = initialsFor(activePartyName);

  useEffect(() => {
    fetch("/api/health").then((response) => setCloudConnected(response.ok)).catch(() => setCloudConnected(false));
    const saved = window.localStorage.getItem("crewboard-settings");
    if (saved) { try { setSettings(JSON.parse(saved)); } catch { /* Keep defaults. */ } }
  }, []);
  useEffect(() => {
    if (data.displayName && !profileDraft) setProfileDraft(data.displayName);
  }, [data.displayName, profileDraft]);
  useEffect(() => {
    function onKey(event: KeyboardEvent) { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setSearchOpen(true); } if (event.key === "Escape") { setSearchOpen(false); setConnectorOpen(false); setDeviceManagerOpen(false); setRepositoryOpen(false); setAgentOpen(false); setTaskOpen(false); setSelectedTaskId(""); setSelectedAgentId(""); } }
    window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey);
  }, []);

  async function signOut() { await createClient().auth.signOut(); window.location.href = "/login"; }
  async function toggleAgent(id: string) { const agent = agents.find((item) => item.id === id); if (!agent) return; try { await data.toggleAgent(agent.row); } catch (reason) { setTaskMessage(reason instanceof Error ? reason.message : "Could not update agent"); } }
  async function addTask(input: { title: string; description: string; assignedAgentId?: string; projectId?: string; priority: string; autoSplit: boolean; splitAgentIds: string[] }) { setTaskMessage(input.autoSplit ? "Creating the split…" : "Adding…"); try { await data.addTask(input); setTaskMessage(""); } catch (reason) { const message = reason instanceof Error ? reason.message : "Could not add task"; setTaskMessage(message); throw reason; } }
  async function createAgent(input: { deviceId: string; name: string; provider: string; model: string; reasoningEffort: string; instructions: string; contextWindowTokens: number | null }) { await data.createAgent(input); }
  async function requestRepository(input: { name: string; deviceId: string; sourceType: "local" | "github"; repositoryUrl?: string }) { await data.requestRepositorySetup(input); }
  async function openRepositorySetup() { const devices = await data.refreshDevices().catch(() => data.devices); if (devices.some(isDeviceOnline)) setRepositoryOpen(true); else setConnectorOpen(true); }
  function openDeviceManager() { setDeviceManagerOpen(true); void data.refresh(); }
  function updateSetting(key: keyof typeof settings) { const next = { ...settings, [key]: !settings[key] }; setSettings(next); window.localStorage.setItem("crewboard-settings", JSON.stringify(next)); }
  async function saveProfile() { if (!data.userId || !profileDraft.trim()) return; setProfileMessage("Saving…"); const supabase = createClient(); const name = profileDraft.trim(); const { error } = await supabase.from("profiles").upsert({ id: data.userId, display_name: name }, { onConflict: "id" }); if (!error) await supabase.auth.updateUser({ data: { display_name: name } }); setProfileMessage(error ? error.message : "Profile saved"); if (!error) data.setDisplayName(name); }
  async function createParty() { if (!partyName.trim()) return; setPartyMessage("Creating…"); try { await data.createParty(partyName); setPartyMessage(`${partyName.trim()} is ready`); setPartyName(""); } catch (reason) { setPartyMessage(reason instanceof Error ? reason.message : "Could not create party"); } }

  const networkItems = useMemo(() => [...agents.map((agent) => ({ name: agent.name, meta: `${agent.model} · ${agent.owner}`, kind: "Agent", status: agent.state, tone: agent.tone })), ...data.members.map((member, index) => ({ name: member.user_id === data.userId ? data.displayName : member.displayName, meta: `${member.role} · ${agents.filter((agent) => agent.row.owner_id === member.user_id).length} agents`, kind: "Person", status: "online", tone: ["violet", "blue", "charcoal"][index % 3] }))].filter((item) => item.name.toLowerCase().includes(networkQuery.toLowerCase())), [agents, data.members, data.userId, data.displayName, networkQuery]);
  const topSection = page === "network" ? "network" : page === "docs" ? "docs" : "workspace";
  const invite = async () => { if (!data.activePartyId) { setPartyMessage("Create or select a party first"); return; } const response = await fetch("/api/invitations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ partyId: data.activePartyId, role: "member" }) }); const result = await response.json(); if (!response.ok) { setPartyMessage(result.error?.message ?? "Could not create invite"); return; } await navigator.clipboard?.writeText(result.url); setCopied(true); window.setTimeout(() => setCopied(false), 1800); };
  const usageTotals = useMemo(() => data.usageEvents.reduce((total, event) => ({
    tokens: total.tokens + event.input_tokens + event.output_tokens,
    cached: total.cached + event.cached_input_tokens,
    cost: total.cost + event.cost_usd,
    duration: total.duration + event.duration_ms,
  }), { tokens: 0, cached: 0, cost: 0, duration: 0 }), [data.usageEvents]);
  const usageBars = useMemo(() => { const buckets = Array.from({ length: 12 }, () => 0); const now = Date.now(); data.usageEvents.forEach((event) => { const age = Math.floor((now - new Date(event.created_at).getTime()) / 3600000); if (age >= 0 && age < 12) buckets[11 - age] += event.input_tokens + event.output_tokens; }); const max = Math.max(...buckets, 1); return buckets.map((value) => Math.max(value ? 8 : 2, Math.round((value / max) * 100))); }, [data.usageEvents]);

  return <main className="dashboard-shell"><header className="global-nav"><div className="nav-brand-wrap"><button className="mobile-menu" aria-label="Open navigation" onClick={() => setMobileNav(!mobileNav)}><MenuRounded /></button><Link className="wordmark" href="/">Crewboard</Link></div><nav className="top-links" aria-label="Global navigation"><Link className={topSection === "workspace" ? "active" : ""} href="/dashboard">Workspace</Link><Link className={topSection === "network" ? "active" : ""} href="/network">Network</Link><Link className={topSection === "docs" ? "active" : ""} href="/docs">Docs</Link></nav><div className="nav-actions"><button className="search-button" onClick={() => setSearchOpen(true)}><SearchRounded /><span>Search</span><kbd>⌘ K</kbd></button><Link className="icon-button" aria-label="Usage" href="/usage"><InsightsOutlined /></Link><Link className="nav-avatar" title="Open profile" aria-label="Open profile" href="/profile">{initialsFor(data.displayName)}</Link></div></header>
    <div className="dashboard-body"><aside className={`side-panel ${mobileNav ? "mobile-open" : ""}`}><Link className="party-switcher" href="/parties"><span className="party-avatar">{activePartyInitials}</span><span><small>ACTIVE PARTY</small><strong>{activePartyName}</strong></span><MoreHorizRounded /></Link><nav className="side-nav" aria-label="Product navigation"><p>Workspace</p><Link className={page === "dashboard" ? "active" : ""} href="/dashboard"><DashboardOutlined />Overview</Link><Link className={page === "repositories" ? "active" : ""} href="/repositories"><FolderOpenOutlined />Repositories <span>{data.projects.length}</span></Link><Link className={page === "agents" ? "active" : ""} href="/agents"><HubOutlined />Agents <span>{agents.length}</span></Link><Link className={page === "tasks" ? "active" : ""} href="/tasks"><TaskAltOutlined />Tasks <span>{tasks.filter((task) => !["completed", "cancelled"].includes(task.status)).length}</span></Link><Link className={page === "activity" ? "active" : ""} href="/activity"><HistoryOutlined />Activity</Link><p>Party</p><Link className={page === "people" ? "active" : ""} href="/people"><GroupsOutlined />People <span>{data.members.length}</span></Link><Link className={page === "devices" ? "active" : ""} href="/devices"><DevicesOutlined />Devices <span>{data.devices.length}</span></Link><Link className={page === "parties" ? "active" : ""} href="/parties"><AutoAwesomeOutlined />Parties</Link><p>Account</p><Link className={page === "usage" ? "active" : ""} href="/usage"><InsightsOutlined />Usage</Link><Link className={page === "settings" ? "active" : ""} href="/settings"><SettingsOutlined />Settings</Link><button className="side-nav-signout" onClick={() => void signOut()}><LogoutRounded />Sign out</button></nav><div className={`connector-status ${connected ? "is-connected" : ""}`}><div className="connector-status-head"><span><i />{connected ? "DEVICE ONLINE" : "CONNECTOR OFFLINE"}</span><LinkRounded /></div><p>{connected ? `${data.devices.filter(isDeviceOnline).length} connected device(s) ready.` : "Connect this computer to add Claude, Codex, or Cursor."}</p><button onClick={() => connected ? openDeviceManager() : setConnectorOpen(true)}>{connected ? "Manage devices" : "Connect device"}<ArrowOutwardRounded /></button></div><Link className="create-party" href="/parties"><AddRounded />New party</Link></aside>
      <section className="main-workspace">
        {data.error && <div className="auth-message">{data.error}</div>}
        {page === "dashboard" && <DashboardContent partyName={activePartyName} agents={agents} tasks={tasks} devices={data.devices.length} members={data.members.length} repositories={data.projects.length} activity={activity} connected={connected} copied={copied} onInvite={invite} onRepository={openRepositorySetup} onConnector={() => setConnectorOpen(true)} onToggleAgent={toggleAgent} onInspectAgent={setSelectedAgentId} />}
        {page === "repositories" && <><PageHeading page={page} actions={<button className="button primary" onClick={openRepositorySetup}><AddRounded />Add repository</button>} />{data.repositorySetups.some((request) => ["pending", "claimed"].includes(request.status)) && <section className="repository-requests">{data.repositorySetups.filter((request) => ["pending", "claimed"].includes(request.status)).map((request) => <div key={request.id}><span className="live-indicator"><i />{request.source_type === "github" ? request.status === "claimed" ? "CLONING ON DEVICE" : "WAITING TO CLONE" : request.status === "claimed" ? "FOLDER PICKER OPEN" : "OPENING ON DEVICE"}</span><strong>{request.name}</strong><small>{request.source_type === "github" ? "The connected computer uses its local GitHub login." : request.status === "claimed" ? "Choose its folder on your computer." : "Waiting for the connector."}</small></div>)}</section>}<div className="repository-grid">{data.projects.map((project) => { const folder = data.deviceFolders.find((item) => item.project_id === project.id); const device = folder ? data.devices.find((item) => item.id === folder.device_id) : null; const taskCount = data.tasks.filter((task) => task.project_id === project.id).length; return <article className="panel repository-card" key={project.id}><header><span className="repository-icon">{project.source_type === "github" ? <GitHub /> : <FolderOpenOutlined />}</span><span className="state-badge ready"><i />ready</span></header><h2>{project.name}</h2><p>{project.repository_url || project.description || "Local repository"}</p><dl><div><dt>Computer</dt><dd>{device?.name || "Connected device"}</dd></div><div><dt>{project.source_type === "github" ? "Clone" : "Folder"}</dt><dd>{folder?.label || "Private local path"}</dd></div><div><dt>Tasks</dt><dd>{taskCount}</dd></div></dl><footer><span><LockOutlined />Files stay on the device</span><button className="row-action" aria-label={`Repository options for ${project.name}`}><MoreHorizRounded /></button></footer></article>; })}<button className="add-device-card repository-add-card" onClick={openRepositorySetup}><span><GitHub /></span><strong>Connect repository</strong><small>Clone a GitHub URL or choose a local folder.</small></button></div></>}
        {page === "network" && <><PageHeading page={page} actions={<button className="button primary" onClick={() => void invite()}>{copied ? <CheckRounded /> : <PersonAddAltOutlined />}{copied ? "Invite copied" : "Invite person"}</button>} /><div className="content-grid"><section className="panel wide-panel"><div className="filter-bar"><div className="inline-search"><SearchRounded /><input value={networkQuery} onChange={(event) => setNetworkQuery(event.target.value)} placeholder="Search people and agents" /></div><span>{networkItems.length} connections</span></div><div className="network-grid">{networkItems.map((item) => <article className="network-card" key={`${item.kind}-${item.name}`}><span className={`network-avatar ${item.tone}`}>{item.kind === "Agent" ? <AutoAwesomeOutlined /> : initialsFor(item.name)}</span><div><strong>{item.name}</strong><small>{item.meta}</small></div><span className={`network-state ${item.status}`}><i />{item.status}</span></article>)}</div></section><aside className="panel insight-card"><span className="section-code">NETWORK HEALTH</span><strong>{agents.length + data.members.length}</strong><p>Available connections across the active party.</p><div className="network-breakdown"><span><i className="purple-fill" />{agents.length} AI agents</span><span><i className="dark-fill" />{data.members.length} people</span><span><i className="green-fill" />{data.devices.filter((device) => device.status === "online").length} devices online</span></div></aside></div></>}
        {page === "parties" && <><PageHeading page={page} /><div className="content-grid"><section className="panel wide-panel"><div className="party-card-list">{data.parties.map((party) => <article className={`party-list-card ${party.id === data.activePartyId ? "active-party" : ""}`} key={party.id}><span className="party-avatar large">{initialsFor(party.name)}</span><div><span className="section-code">{party.id === data.activePartyId ? "ACTIVE" : party.role.toUpperCase()}</span><h2>{party.name}</h2><p>{party.role} · created {timeAgo(party.created_at)} ago</p></div><Link className="button secondary" href="/dashboard" onClick={() => data.selectParty(party.id)}>{party.id === data.activePartyId ? "Open party" : "Switch party"}<ChevronRightRounded /></Link></article>)}{!data.loading && !data.parties.length && <div className="auth-message">You are not in a party yet. Create your first workspace here.</div>}</div></section><aside className="panel form-card"><span className="section-code">NEW PARTY</span><h2>Create a workspace</h2><p>Parties keep members, agents, tasks, and usage separate.</p><label>Party name<input value={partyName} onChange={(event) => setPartyName(event.target.value)} placeholder="Launch team" /></label><button className="button primary" disabled={!partyName.trim()} onClick={createParty}><AddRounded />Create party</button>{partyMessage && <small className="form-message">{partyMessage}</small>}</aside></div></>}
        {page === "agents" && <><PageHeading page={page} actions={<button className="button primary" onClick={() => setAgentOpen(true)}><AddRounded />Create agent</button>} /><section className="provider-summary">{providerTools.map((tool) => <div key={tool.id}><span className={`tool-mark ${tool.provider}`}>{tool.provider.slice(0, 2).toUpperCase()}</span><span><strong>{providerName(tool.provider)}</strong><small>Detected on {deviceById.get(tool.device_id ?? "")?.name || "your computer"}</small></span><span className="state-badge ready"><i />available</span></div>)}{!providerTools.length && <div className="auth-message">Connect a computer to detect Claude Code, Codex, or Cursor.</div>}</section><section className="panel page-panel"><div className="filter-bar"><div className="filter-pills"><button className="active">All {agents.length}</button><button>Ready {agents.filter((agent) => agent.state === "ready").length}</button><button>Working {agents.filter((agent) => agent.state === "working").length}</button><button>Offline {agents.filter((agent) => agent.state === "offline").length}</button></div><span>Click an agent to see its model, computer, instructions, and current task.</span></div><AgentTable agents={agents} onToggle={toggleAgent} onInspect={setSelectedAgentId} />{!agents.length && <div className="empty-agent-state"><HubOutlined /><strong>Create Bob, Martin, or any role you need.</strong><p>Each teammate can use a different model and keep its own standing instructions.</p><button className="button primary" onClick={() => setAgentOpen(true)}><AddRounded />Create your first agent</button></div>}</section><div className="usage-explainer"><InsightsOutlined /><div><strong>About “tokens remaining”</strong><p>Crewboard can show tokens used by each run and an approximate amount left in that run&apos;s context window. Claude, ChatGPT, and Cursor do not expose a reliable live “subscription tokens remaining” number to the connector.</p></div></div></>}
        {page === "tasks" && <><PageHeading page={page} actions={<button className="button primary" onClick={() => setTaskOpen(true)}><AutoAwesomeOutlined />New goal</button>} />{taskMessage && <small className="form-message">{taskMessage}</small>}<div className="task-board">{(["queued", "running", "completed"] as const).map((status) => { const laneTasks = tasks.filter((task) => !task.parentId && (status === "queued" ? !["running", "completed"].includes(task.status) : task.status === status)); return <section className="task-lane" key={status}><header><span>{status === "queued" ? "queue / attention" : status}</span><strong>{laneTasks.length}</strong></header>{laneTasks.map((task) => { const childTasks = tasks.filter((child) => child.parentId === task.id); return <button type="button" className={`task-card task-card-button ${task.status}`} key={task.id} onClick={() => setSelectedTaskId(task.id)}><div className="task-card-meta"><span className="task-kind">{task.kind === "planner" ? "AUTO SPLIT" : task.status === "running" ? "IN PROGRESS" : task.status.toUpperCase()}</span><span className={`priority-chip ${task.priority}`}>{task.priority}</span></div><h3>{task.title}</h3><p>{task.progress || task.description || task.agent}</p>{childTasks.length > 0 && <div className="task-split-progress"><span><i style={{ width: `${Math.round((childTasks.filter((child) => child.status === "completed").length / childTasks.length) * 100)}%` }} /></span><small>{childTasks.filter((child) => child.status === "completed").length}/{childTasks.length} subtasks</small></div>}<small className="task-assignee">{task.agent}</small><footer><span>{initialsFor(task.owner)}</span><small>{task.owner}</small><MoreHorizRounded /></footer></button>; })}</section>; })}</div></>}
        {page === "activity" && <><PageHeading page={page} /><section className="panel page-panel"><div className="filter-bar"><div className="filter-pills"><button className="active">Everything</button><button>People</button><button>Agents</button><button>Tasks</button></div><span className="live-indicator"><i />LIVE</span></div><div className="timeline">{activity.map((item, index) => <article key={index}><span className="activity-avatar large-avatar">{item.initials}</span><div><strong>{item.text}</strong><small>{item.type} · {item.time} ago</small></div><button className="row-action"><MoreHorizRounded /></button></article>)}</div></section></>}
        {page === "people" && <><PageHeading page={page} actions={<button className="button primary" onClick={() => void invite()}>{copied ? <CheckRounded /> : <PersonAddAltOutlined />}{copied ? "Link copied" : "Invite people"}</button>} /><section className="panel page-panel"><div className="member-table member-head"><span>Member</span><span>Role</span><span>Agents</span><span>Joined</span><span /></div>{data.members.map((member) => { const name = member.user_id === data.userId ? data.displayName : member.displayName; return <div className="member-table" key={member.user_id}><div className="member-identity"><span>{initialsFor(name)}</span><div><strong>{name}</strong><small>Crewboard member</small></div></div><span className="role-chip">{member.role}</span><span>{agents.filter((agent) => agent.row.owner_id === member.user_id).length}</span><span>{timeAgo(member.joined_at)} ago</span><button className="row-action"><MoreHorizRounded /></button></div>; })}</section></>}
        {page === "devices" && <><PageHeading page={page} actions={<><button className="button secondary" onClick={openDeviceManager}><TuneRounded />Manage devices</button><button className="button primary" onClick={() => setConnectorOpen(true)}><AddRounded />Connect device</button></>} /><div className="device-grid">{data.devices.map((device) => { const online = isDeviceOnline(device); const tools = providerTools.filter((tool) => tool.device_id === device.id); return <article className="panel device-card" key={device.id}><header><span className="device-icon"><ComputerRounded /></span><span className={`state-badge ${online ? "ready" : "offline"}`}><i />{online ? "online" : "offline"}</span></header><h2>{device.name}</h2><p>{device.platform} · Connector {device.connector_version || "unknown"}</p><div>{tools.map((tool) => <span key={tool.id}><i className="codex-dot" />{providerName(tool.provider)}</span>)}{agents.filter((agent) => agent.row.device_id === device.id).map((agent) => <span key={agent.id}><i className="codex-dot" />{agent.name}</span>)}</div><footer>{device.last_seen_at ? `Seen ${timeAgo(device.last_seen_at)} ago` : "Not seen yet"}<button onClick={openDeviceManager}><TuneRounded />Manage</button></footer></article>; })}<button className="add-device-card" onClick={() => setConnectorOpen(true)}><span><AddRounded /></span><strong>Connect this computer</strong><small>Bring in local AI tools without sharing credentials.</small></button></div></>}
        {page === "usage" && <><PageHeading page={page} actions={<span className={`live-indicator usage-live ${data.realtimeConnected ? "" : "waiting"}`}><i />{data.realtimeConnected ? "UPDATING LIVE" : "CONNECTING"}</span>} /><section className="metrics-grid"><article><span>ESTIMATED COST</span><strong>${usageTotals.cost.toFixed(2)}</strong><small className="positive">From the last 100 events</small></article><article><span>TOTAL TOKENS</span><strong>{usageTotals.tokens.toLocaleString()}</strong><small>{usageTotals.cached.toLocaleString()} cached</small></article><article><span>AGENT RUNS</span><strong>{data.usageEvents.length}</strong><small>Visible usage events</small></article><article><span>AVG. DURATION</span><strong>{data.usageEvents.length ? `${Math.round(usageTotals.duration / data.usageEvents.length / 1000)}s` : "0s"}</strong><small>Across all providers</small></article></section><div className="content-grid"><section className="panel wide-panel usage-chart"><header className="panel-header"><div><span className="section-code">LAST 12 HOURS</span><h2>Token activity</h2></div><span>{usageTotals.tokens.toLocaleString()} tokens</span></header><div className="bar-chart">{usageBars.map((bar, index) => <div key={index}><span style={{ height: `${bar}%` }} /><small>{index % 2 === 0 ? `${index + 1}h` : ""}</small></div>)}</div></section><aside className="panel provider-list"><span className="section-code">BY PROVIDER</span>{Array.from(new Set(data.usageEvents.map((event) => event.provider))).map((provider, index) => { const count = data.usageEvents.filter((event) => event.provider === provider).length; const percent = data.usageEvents.length ? Math.round((count / data.usageEvents.length) * 100) : 0; return <div key={provider}><span><i style={{ background: ["#29262f", "#9f5f3e", "#3165c7"][index % 3] }} />{provider}</span><strong>{percent}%</strong></div>; })}{!data.usageEvents.length && <small>No usage reported yet.</small>}</aside></div></>}
        {page === "profile" && <><PageHeading page={page} /><div className="settings-layout"><aside className="panel profile-summary"><span className="profile-avatar-large">{initialsFor(data.displayName)}</span><h2>{data.displayName}</h2><p>{data.email}</p><span className="role-chip">Crewboard member</span></aside><section className="panel settings-card"><header><div><span className="section-code">IDENTITY</span><h2>Profile details</h2></div></header><div className="settings-form"><label>Display name<input value={profileDraft} onChange={(event) => setProfileDraft(event.target.value)} maxLength={80} /></label><label>Email address<input value={data.email} disabled /><small>Email changes require verification.</small></label><label>Profile ID<input value={data.userId || "Loading…"} disabled /></label><div className="form-actions"><span>{profileMessage}</span><button className="button primary" disabled={!profileDraft.trim()} onClick={saveProfile}>Save profile</button></div></div></section></div></>}
        {page === "settings" && <><PageHeading page={page} /><div className="settings-layout settings-wide"><nav className="panel settings-index"><a href="#approvals" className="active"><ShieldOutlined />Approvals</a><a href="#notifications"><NotificationsNoneRounded />Notifications</a><a href="#privacy"><LockOutlined />Privacy</a><Link href="/profile"><AccountCircleOutlined />Profile</Link></nav><section className="panel settings-card"><header id="approvals"><div><span className="section-code">SAFETY</span><h2>Agent approvals</h2></div></header><SettingRow title="Require approval for sensitive actions" note="Pause before shell writes, publishing, or destructive operations." value={settings.approvals} onChange={() => updateSetting("approvals")} /><header id="notifications"><div><span className="section-code">NOTIFICATIONS</span><h2>Keep me informed</h2></div></header><SettingRow title="Task updates" note="Notify me when an assigned task finishes or needs input." value={settings.taskUpdates} onChange={() => updateSetting("taskUpdates")} /><SettingRow title="Weekly usage digest" note="A short email with tokens, cost, and completed work." value={settings.weeklyDigest} onChange={() => updateSetting("weeklyDigest")} /><header id="privacy"><div><span className="section-code">PRIVACY</span><h2>Presence</h2></div></header><SettingRow title="Show when I am online" note="Party members can see your live availability." value={settings.presence} onChange={() => updateSetting("presence")} /><div className="settings-footer"><button className="button secondary danger-button" onClick={signOut}>Sign out of Crewboard</button></div></section></div></>}
        {page === "docs" && <DocsContent onConnector={() => setConnectorOpen(true)} />}
        <footer className="prototype-note"><span>{cloudConnected ? "CLOUD CONNECTED" : "CONNECTING"}</span> Crewboard keeps credentials local and account data protected by Supabase.</footer>
      </section></div>{connectorOpen && <ConnectorModal partyId={data.activePartyId} onClose={() => setConnectorOpen(false)} onConnected={data.refresh} />}{deviceManagerOpen && <DeviceManagerModal devices={manageableDevices} sessions={data.deviceSessions} onClose={() => setDeviceManagerOpen(false)} onConnect={() => { setDeviceManagerOpen(false); setConnectorOpen(true); }} onRevoke={data.revokeDeviceSession} />}{repositoryOpen && <RepositoryModal devices={data.devices.filter((device) => device.owner_id === data.userId)} onClose={() => setRepositoryOpen(false)} onRequest={requestRepository} onConnect={() => { setRepositoryOpen(false); setConnectorOpen(true); }} />}{agentOpen && <AgentModal tools={providerTools.filter((tool) => tool.owner_id === data.userId)} devices={data.devices.filter((device) => device.owner_id === data.userId)} onClose={() => setAgentOpen(false)} onCreate={createAgent} onConnect={() => { setAgentOpen(false); setConnectorOpen(true); }} />}{taskOpen && <TaskModal agents={agents} projects={data.projects} onClose={() => setTaskOpen(false)} onCreate={addTask} />}{selectedTask && <TaskDetailModal key={selectedTask.id} task={selectedTask} children={tasks.filter((task) => task.parentId === selectedTask.id)} runs={data.taskRuns} progress={data.taskProgress} agents={agents} projects={data.projects} devices={data.devices} onClose={() => setSelectedTaskId("")} onResume={data.resumeTask} onRetry={data.retryTask} onOpenTask={setSelectedTaskId} />}{selectedAgent && <AgentDetailModal agent={selectedAgent} device={data.devices.find((device) => device.id === selectedAgent.row.device_id)} currentTask={tasks.find((task) => task.row.assigned_agent_id === selectedAgent.id && ["running", "queued", "approval_needed"].includes(task.status))} latestRun={data.taskRuns.filter((run) => run.agent_id === selectedAgent.id).sort((left, right) => new Date(right.created_at).getTime() - new Date(left.created_at).getTime())[0]} canEdit={selectedAgent.row.owner_id === data.userId || ["owner", "admin"].includes(data.activeParty?.role ?? "")} onUpdateEffort={data.updateAgentEffort} onClose={() => setSelectedAgentId("")} />}{searchOpen && <SearchPalette onClose={() => setSearchOpen(false)} />}</main>;
}

function DashboardContent({ partyName, agents, tasks, devices, members, repositories, activity, connected, copied, onInvite, onRepository, onConnector, onToggleAgent, onInspectAgent }: { partyName: string; agents: Agent[]; tasks: Task[]; devices: number; members: number; repositories: number; activity: ActivityItem[]; connected: boolean; copied: boolean; onInvite: () => void; onRepository: () => void; onConnector: () => void; onToggleAgent: (id: string) => void; onInspectAgent: (id: string) => void }) {
  return <><PageHeading page="dashboard" partyName={partyName} actions={<><button className="button secondary" onClick={onInvite}>{copied ? <CheckRounded /> : <PersonAddAltOutlined />}{copied ? "Copied" : "Invite"}</button><button className="button primary" onClick={onRepository}><FolderOpenOutlined />Add repository</button></>} /><section className="metrics-grid"><article><span>ONLINE DEVICES</span><strong>{devices}</strong><small><i className="green-dot" />{members} party members</small></article><article><span>REPOSITORIES</span><strong>{repositories}</strong><small>Folders shared with this party</small></article><article><span>OPEN TASKS</span><strong>{tasks.filter((task) => !["completed", "cancelled"].includes(task.status)).length}</strong><small>{tasks.filter((task) => task.status === "running").length} actively running</small></article><article><span>COMPLETED</span><strong>{tasks.filter((task) => task.status === "completed").length}</strong><small className="positive">All recorded work</small></article></section><div className="workspace-grid"><div className="primary-column"><section className="panel"><header className="panel-header"><div><span className="section-code">01 / AGENTS</span><h2>AI teammates</h2></div><Link className="text-button" href="/agents">View all<ChevronRightRounded /></Link></header><AgentTable agents={agents} onToggle={onToggleAgent} onInspect={onInspectAgent} /></section><section className="panel task-preview"><header className="panel-header"><div><span className="section-code">02 / TASKS</span><h2>Work in motion</h2></div><Link className="text-button" href="/tasks">Open board<ChevronRightRounded /></Link></header>{tasks.slice(0, 3).map((task) => <div className="preview-task-row" key={task.id}><span className={`task-status-dot ${task.status}`} /><div><strong>{task.title}</strong><small>{task.agent}</small></div><span className="role-chip">{task.status}</span></div>)}{!tasks.length && <div className="auth-message">No tasks yet. Add the first one from the Tasks page.</div>}</section></div><aside className="secondary-column"><section className="panel compact-panel"><header className="panel-header"><div><span className="section-code">LIVE</span><h2>Party activity</h2></div><span className="live-indicator"><i />LIVE</span></header><div className="activity-list">{activity.slice(0, 4).map((item) => <div className="activity-item" key={item.id}><span className="activity-avatar">{item.initials}</span><p><strong>{item.text}</strong><time>{item.time} ago</time></p></div>)}{!activity.length && <small>No activity yet.</small>}</div><Link className="full-width-link" href="/activity">View full activity<ChevronRightRounded /></Link></section><section className="panel connector-card"><span className="section-code">YOUR CONNECTOR</span><div className="connector-icon"><ComputerRounded /></div><h2>{connected ? "Device online" : "Your AI tools are missing"}</h2><p>{connected ? "At least one connector is available to this party." : "Connect once to bring Claude, Codex, or Cursor into the workspace."}</p><button className="button dark" onClick={connected ? onRepository : onConnector}>{connected ? "Add a repository" : "Connect this computer"}<ArrowOutwardRounded /></button><small><LockOutlined />Credentials always stay on your device.</small></section></aside></div></>;
}
function AgentTable({ agents, onToggle, onInspect }: { agents: Agent[]; onToggle: (id: string) => void; onInspect: (id: string) => void }) { return <div className="agent-table"><div className="agent-table-head"><span>Agent</span><span>Owner</span><span>Status</span><span>Usage</span><span /></div>{agents.map((agent) => <div className="agent-row" key={agent.id}><button type="button" className="agent-identity agent-identity-button" onClick={() => onInspect(agent.id)}><span className={`agent-mark ${agent.tone}`}>{agent.name.charAt(0)}</span><span><strong>{agent.name}</strong><small>{providerName(agent.provider)} · {agent.model} · {effortLabel(agent.row.reasoning_effort)} effort</small></span></button><span className="owner-cell">{agent.owner}</span><StateBadge state={agent.state} /><button type="button" className="task-cell task-cell-button" title={agent.task} onClick={() => onInspect(agent.id)}>{agent.state === "working" ? agent.task : agent.usage}</button><button className="row-action" aria-label={`${agent.state === "paused" ? "Resume" : "Pause"} ${agent.name}`} disabled={agent.state === "offline"} onClick={() => onToggle(agent.id)}>{agent.state === "paused" ? <PlayArrowRounded /> : <PauseRounded />}</button></div>)}</div>; }
function SettingRow({ title, note, value, onChange }: { title: string; note: string; value: boolean; onChange: () => void }) { return <div className="setting-row"><div><strong>{title}</strong><p>{note}</p></div><button className={`toggle ${value ? "on" : ""}`} role="switch" aria-checked={value} onClick={onChange}><span /></button></div>; }

function DocsContent({ onConnector }: { onConnector: () => void }) {
  const [copied, setCopied] = useState(false);
  const [command, setCommand] = useState("npx --yes github:mmvinfo28/crewboard#connector-v0.4.1 connect");
  useEffect(() => { setCommand(`npx --yes github:mmvinfo28/crewboard#connector-v0.4.1 connect --url ${window.location.origin}`); }, []);
  return <><PageHeading page="docs" actions={<button className="button primary" onClick={onConnector}><LinkRounded />Connect a device</button>} /><div className="docs-layout"><aside className="docs-index"><span>GETTING STARTED</span><a className="active" href="#quickstart">Quickstart</a><a href="#connector">Local connector</a><a href="#parties">Parties</a><span>CORE CONCEPTS</span><a href="#agents">Agents</a><a href="#tasks">Tasks and approvals</a><a href="#usage-docs">Usage</a><span>REFERENCE</span><a href="#security">Security model</a><a href="#mcp">MCP and API</a></aside><article className="panel docs-article"><section id="quickstart"><span className="section-code">5 MINUTE SETUP</span><h2>Bring your AI team onto one board.</h2><p>Crewboard is the shared control layer. Your AI tools still run on computers owned by you and your teammates.</p><div className="doc-callout"><ShieldOutlined /><div><strong>Your credentials never enter Crewboard.</strong><p>The connector uses the Claude, Codex, or Cursor login already stored on your machine.</p></div></div></section>{[["01", "connector", "Connect your computer", "Run the connector once, approve a folder, and choose which installed AI tools can join your parties."], ["02", "parties", "Create or join a party", "A party is a private workspace with its own people, agents, tasks, devices, and usage totals."], ["03", "agents", "Create named teammates", "Turn one installed tool into Bob, Martin, or any number of agents with their own model and instructions."], ["04", "tasks", "Delegate work", "Describe the outcome, choose a named agent and repository, then follow the result from the board."], ["05", "usage-docs", "Watch usage live", "Connector events feed the Usage page so the party can understand tokens, model mix, cost, and run duration."]].map(([number, id, title, copy]) => <section id={id} key={id}><span className="doc-number">{number}</span><div><h3>{title}</h3><p>{copy}</p>{id === "connector" && <button className="doc-command" onClick={() => { navigator.clipboard?.writeText(command); setCopied(true); }}><code>{command}</code><span>{copied ? <CheckRounded /> : <ContentCopyRounded />}{copied ? "Copied" : "Copy"}</span></button>}{id === "parties" && <Link className="inline-doc-link" href="/parties">Open Parties<ArrowOutwardRounded /></Link>}{id === "usage-docs" && <Link className="inline-doc-link" href="/usage">View Usage<ArrowOutwardRounded /></Link>}</div></section>)}<section id="security" className="docs-note"><LockOutlined /><div><h3>Security in plain language</h3><p>Crewboard stores coordination data in the cloud. Provider logins and working files stay on the connected computer. Row-level permissions ensure party data is only visible to its members.</p></div></section><section id="mcp"><span className="doc-number"><CodeRounded /></span><div><h3>MCP and connector API</h3><p>The connector can expose a local MCP bridge for compatible clients. The hosted server handles party instructions, presence, and results; it never acts as your model provider.</p></div></section></article></div></>;
}
